import datetime
import re

from ta_moler.events.fzmconsole.genericfzmconsole_lineevent import GenericFZMConsoleLineEvent


class SiteIsResettingDueToFault(GenericFZMConsoleLineEvent):
    """Siteisresettingduetofault event class."""

    def __init__(self, connection, fault_id=None, till_occurs_times=-1, runner=None):
        """
        Event for 'site is resetting due to fault'.

        :param connection: moler connection to device, terminal when command is executed
        :param fault_id: fault id to catch
        :param till_occurs_times: number of event occurrence
        """
        if fault_id:
            self.detect_pattern = f"::SITE RESET: Site is resetting due to Fault (?P<FAULT_ID>{fault_id})"
        else:
            self.detect_pattern = r"::SITE RESET: Site is resetting due to Fault (?P<FAULT_ID>\d+)"

        super(SiteIsResettingDueToFault, self).__init__(
            connection=connection, runner=runner, till_occurs_times=till_occurs_times, detect_patterns=[self.detect_pattern], match="any"
        )

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line or not self.process_full_lines_only:
            match_obj = re.search(self.detect_pattern, line)

            if match_obj:
                current_ret = {}
                current_ret["line"] = line
                current_ret["time"] = self._last_recv_time_data_read_from_connection
                current_ret["fault_id"] = match_obj.group("FAULT_ID")
                self.event_occurred(event_data=current_ret)
                return


